custom_css:
/* ╔══════════════════════════════════════════════════════════════╗
   ║             深蓝 Mica 主题 — 完整增强版                      ║
   ║             by 灰魂 × 主人  ·  2026.02                      ║
   ╚══════════════════════════════════════════════════════════════╝ */

/* ========== 1) CSS 变量 ========= */
:root {
  /* 安全区与布局 */
  --safe-top: env(safe-area-inset-top, 0px);
  --ui-spacing: 10px;
  --ui-border-radius-small: 2px;
  --ui-border-radius-medium: 3px;
  --ui-border-radius-large: 4px;

  /* 颜色（增强版深海蓝） */
  --ui-bg-primary: #05101c;
  --ui-bg-secondary: #0d243b;
  --ui-bg-tertiary: #010c18;

  /* 聊天气泡 */
  --ui-bg-user-mica: rgba(22, 48, 82, 0.88);
  --ui-bg-ai-mica: rgba(12, 22, 36, 0.88);
  --ui-bg-user-solid: #163052;
  --ui-bg-ai-solid: #0c1624;

  /* 文本 — 优先跟随全局设定色，未设定时回退到主题默认 */
  --ui-text-primary: var(--SmartThemeBodyColor, #e0e6f2);
  --ui-text-secondary: #a6b8cc;
  --ui-text-placeholder: #6a8090;

  /* 强调色 */
  --ui-accent-primary: #337ab7;
  --ui-accent-primary-hover: #4a90d6;
  --ui-accent-secondary: #70a1ff;
  --ui-accent-glow: rgba(51, 122, 183, 0.6);

  /* 线条阴影 — 科技感勾边 */
  --ui-border-color: rgba(60, 120, 190, 0.28);
  --ui-shadow-color: rgba(0, 0, 0, 0.45);
  --ui-focus-shadow: 0 0 0 1px rgba(51, 122, 183, 0.6);

  /* Mica 效果 */
  --ui-mica-panel: rgba(5, 16, 28, 0.92);
  --ui-mica-input: rgba(5, 14, 26, 0.95);
  --ui-mica-blur: 18px;
  --ui-mica-blur-chat: 8px;

  /* no-blur 纹理（复用，避免重复 data URI） */
  --ui-noise-texture-strong: url("data:image/svg+xml,%3Csvg viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.07'/%3E%3C/svg%3E");
  --ui-noise-texture-soft: url("data:image/svg+xml,%3Csvg viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.6' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.06'/%3E%3C/svg%3E");

  /* 过渡 */
  --ui-transition-fast: 0.15s ease;
  --ui-transition-normal: 0.25s ease;
}

/* ========== 2) 全局与滚动条 ========= */
body {
  background: var(--ui-bg-primary);
  color: var(--ui-text-primary);
}

/* 全局文本阴影：仅保留在主要文本区域，避免全局重绘 */
:where(.mes_text, .mes_reasoning, .mesIDDisplay, .mes_timer, .tokenCounterDisplay, .ch_name, .drawer-content, .popup, .standoutHeader, .inline-drawer-header) {
  text-shadow: 0px 0px 1px rgba(0, 0, 0, 0.4) !important;
}
:where(input, textarea, select, button, .menu_button, .drawer-icon) {
  text-shadow: none !important;
}
:where(.fa-solid, .fa-regular)::before {
  text-shadow: none !important;
}

/* 滚动条 — 细、自动隐藏（仅限可滚动主容器） */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
  transition: background 0.25s ease;
}
::-webkit-scrollbar-thumb:hover { background: var(--ui-accent-primary); }

:where(#chat, #left-nav-panel, #right-nav-panel, .drawer-content, #select_chat_div, #dialogue_popup_text, #rm_print_characters_block, #character_popup, #floatingPrompt, #cfgConfig, .scrollY) {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  transition: scrollbar-color 0.25s ease;
}
:where(#chat, #left-nav-panel, #right-nav-panel, .drawer-content, #select_chat_div, #dialogue_popup_text, #rm_print_characters_block, #character_popup, #floatingPrompt, #cfgConfig, .scrollY):hover {
  scrollbar-color: rgba(255, 255, 255, 0.12) transparent;
}
:where(#chat, #left-nav-panel, #right-nav-panel, .drawer-content, #select_chat_div, #dialogue_popup_text, #rm_print_characters_block, #character_popup, #floatingPrompt, #cfgConfig, .scrollY)::-webkit-scrollbar-thumb {
  background: transparent;
}
:where(#chat, #left-nav-panel, #right-nav-panel, .drawer-content, #select_chat_div, #dialogue_popup_text, #rm_print_characters_block, #character_popup, #floatingPrompt, #cfgConfig, .scrollY):hover::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
}
:where(#chat, #left-nav-panel, #right-nav-panel, .drawer-content, #select_chat_div, #dialogue_popup_text, #rm_print_characters_block, #character_popup, #floatingPrompt, #cfgConfig, .scrollY):hover::-webkit-scrollbar-thumb:hover {
  background: var(--ui-accent-primary);
}

#chat {
  background: var(--ui-bg-primary) !important;
  border: none !important;
  box-shadow: inset 0 6px 14px -6px rgba(0,0,0,0.28) !important;
}

/* ========== 3) 聊天布局 & 气泡 (Mica 伪元素) ========= */
.mes {
  position: relative !important;
  isolation: isolate;
  display: flex;
  align-items: flex-start;
  gap: var(--ui-spacing);
  padding: var(--ui-spacing);
  margin-bottom: 15px;
  border-radius: var(--ui-border-radius-large);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  filter: none !important;
}

.mes::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  border-radius: inherit !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* ★ 四角科技感勾边 — 分离式准心角标 ★ */
.mes::after,
.mes_reasoning_header::after,
.popup:not(.transparent_dialogue_popup)::after,
#send_form::after,
.select_chat_block::after,
.model-card::after {
  --corner-size: 22px;
  --corner-thickness: 1px;
  --corner-gap: 4px;
  --corner-color: rgba(51, 122, 183, 0.45);
  content: '' !important;
  position: absolute !important;
  inset: 3px !important;
  z-index: 1 !important;
  pointer-events: none !important;
  background:
    /* 左上 水平（右移gap，不到角） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat var(--corner-gap) 0 / var(--corner-size) var(--corner-thickness),
    /* 左上 垂直（下移gap，不到角） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat 0 var(--corner-gap) / var(--corner-thickness) var(--corner-size),
    /* 右上 水平（左移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat calc(100% - var(--corner-gap)) 0 / var(--corner-size) var(--corner-thickness),
    /* 右上 垂直（下移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat 100% var(--corner-gap) / var(--corner-thickness) var(--corner-size),
    /* 左下 水平（右移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat var(--corner-gap) 100% / var(--corner-size) var(--corner-thickness),
    /* 左下 垂直（上移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat 0 calc(100% - var(--corner-gap)) / var(--corner-thickness) var(--corner-size),
    /* 右下 水平（左移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat calc(100% - var(--corner-gap)) 100% / var(--corner-size) var(--corner-thickness),
    /* 右下 垂直（上移gap） */
    linear-gradient(var(--corner-color), var(--corner-color)) no-repeat 100% calc(100% - var(--corner-gap)) / var(--corner-thickness) var(--corner-size) !important;
  opacity: 0.4;
  transition: opacity 0.25s ease;
}

/* 需要 position:relative 来定位 ::after */
.mes_reasoning_header,
.select_chat_block,
.model-card {
  position: relative !important;
}

/* 用户消息勾边略亮 */
.mes[is_user=true]::after {
  opacity: 0.55;
}

/* hover 时勾边微亮 */
.mes:hover::after,
.mes_reasoning_header:hover::after,
.popup:not(.transparent_dialogue_popup):hover::after,
.select_chat_block:hover::after,
.model-card:hover::after {
  opacity: 0.7;
}

/* send_form 勾边始终极淡 */
#send_form::after {
  opacity: 0.3;
  inset: 2px !important;
}

body:not(.no-blur) .mes[is_user=false]::before {
  background: var(--ui-bg-ai-mica) !important;
  backdrop-filter: blur(var(--ui-mica-blur-chat)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur-chat)) !important;
  border: 1px solid var(--ui-border-color) !important;
}

body:not(.no-blur) .mes[is_user=true]::before {
  background: var(--ui-bg-user-mica) !important;
  backdrop-filter: blur(var(--ui-mica-blur-chat)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur-chat)) !important;
  border: 1px solid rgba(80, 144, 211, 0.4) !important;
}

.mes[is_user=false] {
  box-shadow: 0 4px 12px var(--ui-shadow-color);
}

.mes[is_user=true] {
  box-shadow: 0 4px 15px rgba(30, 58, 95, 0.5);
}

.mes:not(.mes_edit):hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 25px var(--ui-shadow-color);
}

/* 选中消息高亮 — 用深蓝替代默认红色 */
#chat .mes.selected {
  background-color: rgba(51, 122, 183, 0.35) !important;
}
#chat .mes.selected::before {
  border-color: var(--ui-accent-primary) !important;
}

/* 重置旧容器 */
.mes_block {
  padding: 0;
  background: none;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  flex-grow: 1;
}
.mes[is_user=false] .mes_block::before,
.mes[is_user=true] .mes_block::before { display: none; }

/* 头像 */
.mes .mesAvatarWrapper { padding-bottom: 0; flex-shrink: 0; }
.mesAvatarWrapper .avatar, .mesAvatarWrapper .avatar img {
  width: 46px; height: 46px; border-radius: 50%;
}
.mesAvatarWrapper .avatar img {
  border: 2px solid transparent;
  transition: all 0.3s ease;
}
.mes[is_user=false] .mesAvatarWrapper .avatar img {
  border-color: var(--ui-text-secondary);
  box-shadow: 0 0 10px rgba(166,184,204,0.4);
}
.mes[is_user=true] .mesAvatarWrapper .avatar img {
  border-color: var(--ui-accent-primary);
  box-shadow: 0 0 12px rgba(80,144,211,0.6);
}
.mesAvatarWrapper .avatar img:hover {
  transform: scale(1.08);
  box-shadow: 0 0 20px rgba(80,144,211,0.8);
}

/* 文本/链接/时间 */
.mes_text a { color: var(--ui-accent-secondary); text-decoration: underline; }
.mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  margin: 0 5px; color: var(--ui-text-secondary); opacity: 0.7; font-size: 0.85em;
}

/* Context 边界线 — 蓝色替代默认橙色 */
.lastInContext {
  border-top: 3px dotted var(--ui-accent-primary) !important;
}

/* HR 分割线 — 蓝色渐变 */
.mes_text hr, .mes_reasoning hr {
  background-image: linear-gradient(90deg, transparent, var(--ui-accent-primary), transparent) !important;
  opacity: 0.3;
}

/* ========== 4) 底部设置栏 (Mica 伪元素) ========= */
#top-settings-holder {
  position: absolute !important;
  bottom: 0 !important;
  width: 100% !important;
  z-index: 1001 !important;
  pointer-events: auto !important;
  border-top: 1px solid var(--ui-accent-primary) !important;
  box-shadow: 0 -4px 20px var(--ui-shadow-color) !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  filter: none !important;
  perspective: none !important;
  contain: none !important;
  will-change: auto !important;
}

body:not(.no-blur) #top-settings-holder::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--ui-mica-panel) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
  z-index: -1 !important;
  pointer-events: none !important;
  transform: none !important;
  filter: none !important;
}

/* Drawer 弹层 */
body:not(.no-blur) #top-settings-holder .drawer .drawer-content {
  position: fixed !important;
  top: var(--safe-top) !important;
  max-height: calc(100dvh - var(--topBarBlockSize, 45px) - var(--safe-top)) !important;
  overflow-y: auto !important;
  background: var(--ui-mica-panel) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
  border: 1px solid var(--ui-border-color) !important;
  border-bottom: none !important;
  border-radius: var(--ui-border-radius-medium) var(--ui-border-radius-medium) 0 0 !important;
  z-index: 1002 !important;
  transform: none !important;
  filter: none !important;
}

/* Drawer 设置面板内容 — Mica 适配 */
.drawer-content {
  background: var(--ui-mica-panel) !important;
  border: 1px solid var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}

/* ========== 5) 侧栏 (Mica 伪元素 + 动画) ========= */
#left-nav-panel, #right-nav-panel {
  position: fixed !important;
  top: var(--safe-top) !important;
  height: calc(100dvh - var(--bottomFormBlockSize, 60px) - var(--topBarBlockSize, 45px) - var(--safe-top)) !important;
  max-height: calc(100dvh - var(--bottomFormBlockSize, 60px) - var(--topBarBlockSize, 45px) - var(--safe-top)) !important;
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-medium) !important;
  box-shadow: 0 4px 15px var(--ui-shadow-color) !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  filter: none !important;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.25s ease,
              visibility 0.25s ease !important;
}

/* 左侧面板滑入动画 */
#left-nav-panel {
  transform-origin: left center !important;
}

/* 右侧面板滑入动画 */
#right-nav-panel {
  transform-origin: right center !important;
}

body:not(.no-blur) #left-nav-panel::before,
body:not(.no-blur) #right-nav-panel::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--ui-mica-panel) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
  z-index: -1 !important;
  pointer-events: none !important;
  border-radius: inherit !important;
}

/* 遮罩 & 浮动面板贴顶 */
#sheld, .openDrawer { position: fixed !important; top: var(--safe-top) !important; }
#floatingPrompt, #cfgConfig, #logprobsViewer, #movingDivs>div { top: var(--safe-top) !important; }

/* ========== 6) 发送区域 (Mica 伪元素) ========= */
#send_form {
  position: relative !important;
  border-top: 1px solid var(--ui-border-color) !important;
  border-color: rgba(30, 70, 120, 0.15) !important;
  border-radius: 0 0 var(--ui-border-radius-medium) var(--ui-border-radius-medium) !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  filter: none !important;
}

body:not(.no-blur) #send_form::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--ui-mica-input) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  z-index: -1 !important;
  pointer-events: none !important;
  border-radius: 0 0 var(--ui-border-radius-medium) var(--ui-border-radius-medium) !important;
}


/* ★ 输入框 ★ */
#send_textarea {
  background: rgba(8, 18, 32, 0.88) !important;
  color: var(--ui-text-primary) !important;
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-medium) !important;
  min-height: 36px !important;
  padding: 8px 12px !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
  field-sizing: unset;
}
#send_textarea:focus {
  border-color: var(--ui-accent-primary) !important;
  box-shadow: var(--ui-focus-shadow);
  background: rgba(6, 14, 26, 0.92) !important;
}
#send_textarea::placeholder {
  color: var(--ui-text-placeholder) !important;
}

/* ========== 7) 弹窗 (Mica 伪元素) ========= */
body:not(.no-blur) .popup:not(.transparent_dialogue_popup) {
  position: relative !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  filter: none !important;
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-large) !important;
  box-shadow: 0 10px 30px var(--ui-shadow-color) !important;
}

body:not(.no-blur) .popup:not(.transparent_dialogue_popup)::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--ui-mica-panel) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
  border-radius: inherit !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* ========== 8) UI 元素 ========= */
/* 标题/分组头 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader, .inline-drawer-header {
  background: rgba(19, 47, 76, 0.6) !important;
  background-image: none !important;
  color: var(--ui-text-primary);
  border-left: 4px solid var(--ui-accent-primary);
  padding-left: 10px;
  border-radius: 0 var(--ui-border-radius-small) var(--ui-border-radius-small) 0 !important;
  margin-bottom: 8px;
}

/* 输入框/下拉 */
input[type="text"], input[type="number"], input[type="password"],
input[type="search"], textarea, .text_pole, select {
  background: var(--ui-bg-secondary) !important;
  border: 1px solid var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
  border-radius: var(--ui-border-radius-small);
  transition: border-color 0.2s, box-shadow 0.2s;
}
input:focus, textarea:focus, .text_pole:focus, select:focus {
  border-color: var(--ui-accent-primary) !important;
  box-shadow: var(--ui-focus-shadow);
  outline: none;
}
::placeholder { color: var(--ui-text-placeholder) !important; }

/* 编辑文本框 — 统一深色 */
.edit_textarea, .reasoning_edit_textarea {
  background: rgba(8, 18, 30, 0.85) !important;
  border: 1px solid var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
  border-radius: var(--ui-border-radius-small) !important;
}

/* 按钮 */
.menu_button, button {
  background: var(--ui-bg-secondary);
  color: var(--ui-text-primary);
  border: 1px solid var(--ui-border-color);
  border-radius: var(--ui-border-radius-small);
  transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.1s ease;
  box-shadow: none; text-shadow: none;
}
.menu_button:hover, button:hover {
  background: rgba(19, 47, 76, 0.8);
  border-color: var(--ui-accent-primary);
  transform: translateY(-1px);
}
.menu_button:active, button:active {
  background: var(--ui-accent-primary);
  color: var(--ui-bg-primary);
  transform: translateY(0);
}

/* 复选框 */
input[type="checkbox"] {
  appearance: none; -webkit-appearance: none;
  width: 16px; height: 16px;
  border: 1px solid var(--ui-border-color);
  border-radius: 3px;
  background: var(--ui-bg-secondary);
  position: relative; cursor: pointer;
}
input[type="checkbox"]:checked {
  background: var(--ui-accent-primary);
  border-color: var(--ui-accent-primary);
}
input[type="checkbox"]:checked::before {
  content: '✔';
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 12px; color: var(--ui-bg-primary); line-height: 1;
}

/* ========== 9) Range 滑块 — 科技感方形 ========= */
input[type="range"] {
  background: linear-gradient(90deg, rgba(51, 122, 183, 0.4), rgba(51, 122, 183, 0.15)) !important;
  box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.6) !important;
  filter: none !important;
  height: 4px !important;
  border-radius: 2px !important;
}
input[type="range"]:hover {
  background: linear-gradient(90deg, rgba(51, 122, 183, 0.55), rgba(51, 122, 183, 0.25)) !important;
  filter: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  width: 14px !important;
  height: 14px !important;
  background: var(--ui-bg-secondary) !important;
  border: 1px solid var(--ui-accent-primary) !important;
  border-radius: 2px !important;
  box-shadow: 0 0 6px var(--ui-accent-glow), inset 0 0 4px rgba(51, 122, 183, 0.3) !important;
  cursor: ew-resize !important;
  transition: box-shadow 0.2s ease, border-color 0.2s ease !important;
}
input[type="range"]::-webkit-slider-thumb:hover {
  border-color: var(--ui-accent-primary-hover) !important;
  box-shadow: 0 0 10px var(--ui-accent-glow), inset 0 0 6px rgba(51, 122, 183, 0.5) !important;
}
input[type="range"]::-moz-range-thumb {
  width: 14px !important;
  height: 14px !important;
  background: var(--ui-bg-secondary) !important;
  border: 1px solid var(--ui-accent-primary) !important;
  border-radius: 2px !important;
  box-shadow: 0 0 6px var(--ui-accent-glow), inset 0 0 4px rgba(51, 122, 183, 0.3) !important;
  cursor: ew-resize !important;
}

.neo-range-slider {
  background: linear-gradient(90deg, rgba(51, 122, 183, 0.4), rgba(51, 122, 183, 0.15)) !important;
  box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.6) !important;
  filter: none !important;
}
.neo-range-slider:hover {
  background: linear-gradient(90deg, rgba(51, 122, 183, 0.55), rgba(51, 122, 183, 0.25)) !important;
  filter: none !important;
}
.neo-range-input {
  background: var(--ui-bg-secondary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}

/* ========== 10) 底栏图标 ========= */
#top-settings-holder .drawer-icon { opacity: .8; transition: color .2s, opacity .2s; }
#top-settings-holder .drawer-icon:before { font-size: 22px; color: var(--ui-text-secondary); }
#top-settings-holder .drawer-icon:hover:before,
#top-settings-holder .drawer:focus-within .drawer-icon:before { color: var(--ui-accent-primary); opacity: 1; }
#top-settings-holder .openIcon:before,
#top-settings-holder .openIcon:hover:before { color: var(--ui-accent-primary); }

#nonQRFormItems .fa-solid::before,
#nonQRFormItems .fa-regular::before {
  font-size: 20px; color: var(--ui-text-secondary); transition: color 0.2s;
}
#nonQRFormItems .fa-solid:hover::before,
#nonQRFormItems .fa-regular:hover::before { color: var(--ui-accent-primary); }

#send_but:before { color: var(--ui-accent-primary) !important; transition: color 0.2s; }
#send_but:hover:before { color: var(--ui-accent-primary-hover) !important; }

/* ========== 11) 代码块 & 语法高亮 ========= */
.mes_text pre, .mes_reasoning pre {
  background: var(--ui-bg-tertiary);
  border: 1px solid var(--ui-border-color);
  border-radius: var(--ui-border-radius-medium);
  padding: 1em;
}
.mes_text code, .mes_reasoning code {
  color: var(--ui-text-primary);
  background: rgba(5, 16, 28, 0.8) !important;
  border-color: var(--ui-border-color) !important;
}
/* 代码复制按钮 */
.code-copy {
  color: var(--ui-text-secondary) !important;
  opacity: 0.5 !important;
  transition: color var(--ui-transition-fast), opacity var(--ui-transition-fast) !important;
}
.code-copy:hover {
  color: var(--ui-accent-primary) !important;
  opacity: 1 !important;
}

/* ========== 12) 快速回复 ========= */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
  background: rgba(80, 144, 211, 0.15) !important;
  border: 1px solid rgba(51, 122, 183, 0.5) !important;
  color: var(--ui-text-secondary) !important;
  border-radius: var(--ui-border-radius-small) !important;
  transition: all 0.2s ease;
}
#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
  background: rgba(80, 144, 211, 0.4) !important;
  transform: translateY(-1px);
}

/* ========== 13) 消息操作按钮 ========= */
.mes_button, .extraMesButtons>div {
  opacity: 0.7; color: var(--ui-text-secondary); transition: opacity 0.2s ease, color 0.2s ease;
}
.mes_button:hover, .extraMesButtons>div:hover {
  opacity: 1; color: var(--ui-accent-primary);
}
.mes[is_user=true] .mes_edit_buttons *:before { color: var(--ui-text-secondary) !important; }
.mes[is_user=true] .mes_edit_buttons *:hover:before { color: var(--ui-accent-primary) !important; }

/* ========== 14) Reasoning 思维链 ========= */
.mes_reasoning {
  border-left-color: rgba(51, 122, 183, 0.5) !important;
}
.mes_reasoning_header {
  background: rgba(13, 36, 59, 0.7) !important;
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-medium) !important;
  color: var(--ui-text-secondary) !important;
  transition: all var(--ui-transition-fast) !important;
}
.mes_reasoning_header:hover {
  background: rgba(19, 47, 76, 0.8) !important;
  border-color: var(--ui-accent-primary) !important;
  color: var(--ui-text-primary) !important;
}
.mes_reasoning button {
  background: var(--ui-bg-secondary);
  color: var(--ui-text-secondary);
  border: 1px solid var(--ui-border-color);
  border-radius: var(--ui-border-radius-medium);
  transition: all 0.2s ease;
}
.mes_reasoning button:hover {
  background: var(--ui-bg-user-solid);
  border-color: var(--ui-accent-primary);
  color: var(--ui-text-primary);
}

/* ========== 15) Swipe 滑动按钮 ========= */
.swipe_right, .swipe_left {
  color: var(--ui-text-secondary) !important;
  transition: all var(--ui-transition-fast) !important;
  filter: drop-shadow(0 0 2px rgba(0,0,0,0.5)) !important;
}
.swipe_right:hover, .swipe_left:hover {
  color: var(--ui-accent-primary) !important;
  opacity: 1 !important;
  filter: drop-shadow(0 0 6px var(--ui-accent-glow)) !important;
}
.swipes-counter {
  color: var(--ui-text-secondary) !important;
}

/* ========== 16) 右侧面板 & 标签按钮 ========= */
.right_menu_button {
  color: var(--ui-text-secondary) !important;
  transition: color var(--ui-transition-fast), filter var(--ui-transition-fast) !important;
}
.right_menu_button:hover,
.right_menu_button.active {
  color: var(--ui-accent-primary) !important;
  filter: drop-shadow(0 0 4px var(--ui-accent-glow)) brightness(130%) !important;
}

/* ========== 17) 角色列表 & 卡片 ========= */
.character_select, .bogus_folder_select {
  border-radius: var(--ui-border-radius-medium) !important;
  transition: background-color var(--ui-transition-fast), box-shadow var(--ui-transition-fast) !important;
}
.character_select:hover, .bogus_folder_select:hover {
  background: rgba(19, 47, 76, 0.5) !important;
  box-shadow: inset 0 0 0 1px var(--ui-border-color) !important;
}
.avatar-container {
  transition: background-color var(--ui-transition-fast), outline-color var(--ui-transition-fast), border-color var(--ui-transition-fast) !important;
  border-radius: var(--ui-border-radius-medium) !important;
}
.avatar-container:hover {
  background: rgba(19, 47, 76, 0.5) !important;
  outline-color: var(--ui-border-color) !important;
}
.avatar-container.selected {
  border-color: var(--ui-accent-primary) !important;
}
/* 角色名称 — 跟随全局设定的主要文字色 */
.ch_name {
  color: var(--SmartThemeBodyColor, var(--ui-text-primary)) !important;
}

/* 预设条目名称（启用）— 正常文字色 */
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled)
  .completion_prompt_manager_prompt_name,
.prompt_order > div > span,
.inline-drawer-header b, .inline-drawer-header span,
.standoutHeader b, .standoutHeader span {
  color: rgba(224, 230, 242, 0.9) !important;
}

/* 预设条目名称（未启用）— 暗色 */
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background: rgba(6, 14, 24, 0.42) !important;
  border: 1px solid rgba(60, 120, 190, 0.15) !important;
  opacity: 0.68 !important;
}

#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled
  .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled
  .completion_prompt_manager_prompt_name .prompt-manager-inspect-action,
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled
  .prompt_manager_prompt_tokens,
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled
  .prompt-manager-toggle-action {
  color: rgba(166, 184, 204, 0.56) !important;
}

#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled:hover {
  opacity: 0.78 !important;
}

/* ========== 18) 选择框下拉选项 ========= */
select option {
  background-color: var(--ui-bg-secondary) !important;
  color: var(--ui-text-primary) !important;
}
select option:checked {
  background-color: var(--ui-accent-primary) !important;
  color: #fff !important;
}
select option:not(:checked) {
  background-color: var(--ui-bg-primary) !important;
  color: var(--ui-text-secondary) !important;
}

/* ========== 19) Toast 通知 ========= */
body #toast-container .toast-success {
  background-color: rgba(35, 90, 70, 0.95) !important;
  border-left: 4px solid #4caf50 !important;
}
body #toast-container .toast-error {
  background-color: rgba(100, 30, 30, 0.95) !important;
  border-left: 4px solid #f44336 !important;
}
body #toast-container .toast-info {
  background-color: rgba(20, 60, 100, 0.95) !important;
  border-left: 4px solid var(--ui-accent-primary) !important;
}
body #toast-container .toast-warning {
  background-color: rgba(120, 80, 20, 0.95) !important;
  border-left: 4px solid #ff9800 !important;
}
body #toast-container > div {
  border-radius: var(--ui-border-radius-medium) !important;
  backdrop-filter: blur(10px) !important;
  box-shadow: 0 4px 15px rgba(0,0,0,0.4) !important;
}

/* ========== 20) 分页组件 ========= */
.paginationjs-pages ul li a {
  color: var(--ui-text-secondary) !important;
  border-color: var(--ui-border-color) !important;
  background: var(--ui-bg-secondary) !important;
  transition: all var(--ui-transition-fast) !important;
}
.paginationjs-pages ul li a:hover {
  border-color: var(--ui-accent-primary) !important;
  color: var(--ui-text-primary) !important;
  background: rgba(51, 122, 183, 0.2) !important;
}
.paginationjs-pages ul li.active a {
  color: var(--ui-accent-primary) !important;
  border-color: var(--ui-accent-primary) !important;
  background: rgba(51, 122, 183, 0.15) !important;
}

/* ========== 21) 模型卡片 ========= */
.model-card {
  background: var(--ui-bg-secondary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
  transition: background-color var(--ui-transition-fast), border-color var(--ui-transition-fast), box-shadow var(--ui-transition-fast) !important;
}
.model-card:hover {
  background: rgba(19, 47, 76, 0.8) !important;
  border-color: var(--ui-accent-primary) !important;
  box-shadow: 0 0 10px var(--ui-accent-glow) !important;
}
.model-card.selected {
  border-color: #4caf50 !important;
  background: rgba(35, 90, 70, 0.5) !important;
}

/* ========== 22) 聊天选择弹窗 ========= */
.select_chat_block {
  border-color: var(--ui-border-color) !important;
  transition: background-color var(--ui-transition-fast), border-color var(--ui-transition-fast) !important;
}
.select_chat_block:hover {
  background: rgba(19, 47, 76, 0.5) !important;
  border-color: var(--ui-accent-primary) !important;
}
.select_chat_block[highlight] {
  background: rgba(51, 122, 183, 0.2) !important;
}
#select_chat_popup {
  background: var(--ui-bg-primary) !important;
  border-color: var(--ui-border-color) !important;
}

/* ========== 23) Prompt Order 拖拽块 ========= */
.prompt_order > div {
  background: var(--ui-bg-secondary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}
.prompt_order:not(.ui-sortable-disabled) > div:hover {
  background: rgba(19, 47, 76, 0.7) !important;
  border-color: var(--ui-accent-primary) !important;
}
.prompt_order .disabled {
  opacity: 0.4 !important;
}

/* ========== 24) 联机状态指示灯 — 方形 ========= */
.online_status_indicator {
  border-radius: 2px !important;
  box-shadow: 0 0 4px currentColor !important;
}
.online_status_indicator.success {
  background-color: #4caf50 !important;
  box-shadow: 0 0 4px rgba(76, 175, 80, 0.6) !important;
}

/* ========== 25) Show More 按钮 ========= */
#show_more_messages {
  background: var(--ui-bg-secondary) !important;
  outline-color: var(--ui-border-color) !important;
  color: var(--ui-text-secondary) !important;
  transition: all var(--ui-transition-fast) !important;
}
#show_more_messages:hover {
  background: rgba(19, 47, 76, 0.7) !important;
  outline-color: var(--ui-accent-primary) !important;
  color: var(--ui-text-primary) !important;
}

/* ========== 26) 全局链接色 — 限定在正文链接 ========= */
.mes_text a, .mes_reasoning a {
  color: var(--ui-accent-secondary) !important;
  text-decoration: underline !important;
}
.mes_text a:hover, .mes_reasoning a:hover {
  color: var(--ui-accent-primary-hover) !important;
  filter: none !important;
}
/* 面板内链接保持正常文字色 */
#left-nav-panel a, #right-nav-panel a,
.drawer-content a, .popup a,
#dialogue_popup a, #character_popup a {
  color: var(--ui-text-primary) !important;
}
#left-nav-panel a:hover, #right-nav-panel a:hover,
.drawer-content a:hover, .popup a:hover {
  color: var(--ui-accent-primary) !important;
  filter: none !important;
}

/* ========== 27) Autocomplete 自动补全 ========= */
.autoComplete, .autoComplete-details {
  background: var(--ui-bg-primary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}
.autoComplete > .item:hover > *,
.autoComplete > .item.selected > * {
  background-color: rgba(19, 47, 76, 0.7) !important;
}

/* ========== 28) Options 右键菜单 & 扩展菜单 ========= */
#options, #extensionsMenu, .popup .popper-modal {
  background: var(--ui-mica-panel) !important;
  border: 1px solid var(--ui-border-color) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
}
.options-content, .list-group {
  border-color: var(--ui-border-color) !important;
  background: var(--ui-bg-primary) !important;
}
.options-content a, #extensionsMenu > .extension_container > div,
#extensionsMenu > div:not(.extension_container),
.list-group > div, .list-group .list-group-item {
  color: var(--ui-text-primary) !important;
}

/* ========== 29) Dialogue 弹窗 ========= */
#dialogue_popup, #bulk_tag_popup {
  background: var(--ui-bg-primary) !important;
  border-color: var(--ui-border-color) !important;
  box-shadow: 0 0 20px rgba(0,0,0,0.6) !important;
}

/* ========== 30) Character Popup ========= */
#character_popup {
  background: var(--ui-mica-panel) !important;
  border-color: var(--ui-border-color) !important;
}
#shadow_character_popup {
  background: rgba(0, 8, 16, 0.7) !important;
}

/* ========== 31) 小图标点缀 ========= */
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt
  .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--ui-accent-primary);
}

/* ========== 32) 彻底隐藏顶部栏 ========= */
#top-bar {
  height: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  overflow: hidden !important;
  pointer-events: none !important;
  opacity: 0 !important;
}

/* ========== 33) jQuery UI 元素适配 ========= */
body .ui-widget-content {
  background-color: var(--ui-bg-primary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}
body .ui-slider-handle {
  background: var(--ui-bg-secondary) !important;
  border-color: var(--ui-border-color) !important;
  color: var(--ui-text-primary) !important;
}
body .ui-slider-handle.ui-state-hover,
body .ui-slider-handle.ui-state-active {
  background: rgba(19, 47, 76, 0.9) !important;
  border-color: var(--ui-accent-primary) !important;
}

/* ========== 34) Shadow Popup 遮罩 ========= */
#shadow_popup {
  background-color: rgba(0, 8, 16, 0.5) !important;
}

/* ========== 35) Suggested Replies ========= */
.suggested_reply {
  border-color: var(--ui-border-color) !important;
  color: var(--ui-accent-secondary) !important;
  transition: background-color var(--ui-transition-fast), border-color var(--ui-transition-fast), color var(--ui-transition-fast) !important;
}
.suggested_reply:hover {
  background: rgba(51, 122, 183, 0.15) !important;
  border-color: var(--ui-accent-primary) !important;
}

/* ========== 36) Info Block ========= */
.info-block {
  background: var(--ui-bg-secondary) !important;
  color: var(--ui-text-primary) !important;
}
.info-block.hint {
  border-color: var(--ui-accent-primary) !important;
  background: rgba(51, 122, 183, 0.1) !important;
}

/* ========== 37) Settings Section Wrap ========= */
.settingsSectionWrap {
  border-color: var(--ui-border-color) !important;
  background: rgba(5, 16, 28, 0.3) !important;
}
.userSettingsInnerExpandable {
  border-color: var(--ui-border-color) !important;
  background: rgba(5, 16, 28, 0.2) !important;
}

/* ========== 38) World Info / Floating Prompt panels ========= */
#floatingPrompt, #cfgConfig {
  background: var(--ui-bg-primary) !important;
  border-color: var(--ui-border-color) !important;
}

/* ========== 39) 降低动态开销（保留风格） ========= */
@media (prefers-reduced-motion: reduce) {
  .mes,
  .mes::after,
  .menu_button,
  button,
  .mes_button,
  .extraMesButtons>div,
  .right_menu_button,
  .character_select,
  .bogus_folder_select,
  .avatar-container,
  .model-card,
  .select_chat_block,
  .suggested_reply {
    transition: none !important;
  }

  .mes:not(.mes_edit):hover,
  .menu_button:hover,
  button:hover,
  #qr--bar > .qr--buttons .qr--button:hover,
  #qr--popout > .qr--body > .qr--buttons .qr--button:hover {
    transform: none !important;
  }
}

/* ========== 40) Blockquote 引用块 — 蓝色发光左线 ========= */
.mes_text blockquote,
.mes_reasoning blockquote {
  border-left: 3px solid var(--ui-accent-primary) !important;
  background-color: rgba(13, 36, 59, 0.5) !important;
  padding: 8px 12px !important;
  margin: 6px 0 !important;
  border-radius: 0 var(--ui-border-radius-small) var(--ui-border-radius-small) 0 !important;
  box-shadow: -3px 0 8px -2px var(--ui-accent-glow) !important;
}

/* ========== 41) 消息内表格 — 深蓝斑马纹 ========= */
.mes_text table,
.mes_reasoning table {
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-small) !important;
  overflow: hidden !important;
  border-spacing: 0 !important;
  border-collapse: collapse !important;
  width: 100% !important;
}
.mes_text th,
.mes_reasoning th {
  background: linear-gradient(135deg, rgba(19, 47, 76, 0.9), rgba(13, 36, 59, 0.8)) !important;
  color: var(--ui-text-primary) !important;
  border: 1px solid var(--ui-border-color) !important;
  padding: 6px 10px !important;
  font-weight: 600 !important;
}
.mes_text td,
.mes_reasoning td {
  border: 1px solid rgba(60, 120, 190, 0.15) !important;
  padding: 5px 10px !important;
  color: var(--ui-text-primary) !important;
}
.mes_text tr:nth-child(even),
.mes_reasoning tr:nth-child(even) {
  background: rgba(13, 36, 59, 0.35) !important;
}
.mes_text tr:nth-child(odd),
.mes_reasoning tr:nth-child(odd) {
  background: rgba(5, 16, 28, 0.25) !important;
}
.mes_text tr:hover,
.mes_reasoning tr:hover {
  background: rgba(51, 122, 183, 0.12) !important;
}

/* ========== 42) kbd 键盘按键 — 深蓝适配 ========= */
kbd {
  background-color: rgba(13, 36, 59, 0.9) !important;
  color: var(--ui-text-primary) !important;
  border: 1px solid var(--ui-border-color) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4), inset 0 -1px 0 rgba(51, 122, 183, 0.3) !important;
  border-radius: 3px !important;
  padding: 2px 5px !important;
  font-size: 90% !important;
}

/* ========== 43) 消息图片/视频容器 ========= */
.mes .mes_img_container,
.mes .mes_video_container {
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-medium) !important;
  overflow: hidden !important;
}
.mes_img_controls,
.mes_video_controls {
  background: linear-gradient(rgba(5, 16, 28, 0.85), transparent) !important;
}
.mes_img_swipes {
  background: linear-gradient(transparent, rgba(5, 16, 28, 0.85)) !important;
}

/* ========== 44) 群聊成员列表 ========= */
.group_member {
  border-radius: var(--ui-border-radius-medium) !important;
  transition: background-color var(--ui-transition-fast), outline-color var(--ui-transition-fast) !important;
}
.group_member:hover {
  background: rgba(19, 47, 76, 0.5) !important;
}
.group_member.is_active {
  outline-color: var(--ui-accent-primary) !important;
  box-shadow: 0 0 6px var(--ui-accent-glow) !important;
}
.group_member.is_queued {
  outline-color: rgba(248, 211, 0, 0.6) !important;
}

/* ========== 45) 小型系统消息 ========= */
.mes.smallSysMes {
  background: rgba(5, 16, 28, 0.4) !important;
  border: 1px solid rgba(60, 120, 190, 0.15) !important;
  border-radius: var(--ui-border-radius-medium) !important;
  opacity: 0.85 !important;
}
.mes.smallSysMes .mes_text {
  color: var(--ui-text-secondary) !important;
  font-style: italic !important;
}

/* ========== 46) Draggable 拖拽面板 ========= */
.draggable {
  background: var(--ui-mica-panel) !important;
  backdrop-filter: blur(var(--ui-mica-blur)) !important;
  -webkit-backdrop-filter: blur(var(--ui-mica-blur)) !important;
  border: 1px solid var(--ui-border-color) !important;
  border-radius: var(--ui-border-radius-large) !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5) !important;
}
.drag-grabber {
  color: var(--ui-text-secondary) !important;
}
.dragClose {
  color: var(--ui-text-secondary) !important;
}
.dragClose:hover {
  color: var(--ui-accent-primary) !important;
}

/* ========== 47) 放大头像查看器 ========= */
.zoomed_avatar {
  border-radius: var(--ui-border-radius-large) !important;
  box-shadow: 0 0 30px rgba(0, 0, 0, 0.7) !important;
}
.zoomed_avatar img {
  border-radius: var(--ui-border-radius-large) !important;
}

/* ========== 48) 标签发光 ========= */
.tag {
  border: 1px solid rgba(51, 122, 183, 0.35) !important;
  border-radius: var(--ui-border-radius-small) !important;
  transition: border-color var(--ui-transition-fast), box-shadow var(--ui-transition-fast) !important;
}
.tag:hover {
  border-color: var(--ui-accent-primary) !important;
  box-shadow: 0 0 6px var(--ui-accent-glow) !important;
}

/* ========== 49) Show More 脉动 ========= */
@keyframes showMorePulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(51, 122, 183, 0); }
  50% { box-shadow: 0 0 12px 2px var(--ui-accent-glow); }
}
#show_more_messages {
  animation: showMorePulse 2.5s ease-in-out infinite !important;
}
#show_more_messages:hover {
  animation: none !important;
  box-shadow: 0 0 10px var(--ui-accent-glow) !important;
}

/* ========== 50) 正在生成脉动 ========= */
@keyframes generatingPulse {
  0%, 100% { box-shadow: 0 4px 12px var(--ui-shadow-color), inset 0 0 0 1px var(--ui-border-color); }
  50% { box-shadow: 0 0 18px var(--ui-accent-glow), inset 0 0 0 1px var(--ui-accent-primary); }
}
body[data-generating="true"] #chat .last_mes::before {
  animation: generatingPulse 2s ease-in-out infinite !important;
}

/* ========== 51) 流式输出性能优化 ========= */

/* 限制消息文本重排范围 */
.mes_text, .mes_reasoning {
  contain: content;
}

/* 流式生成中：最后一条消息降低视觉复杂度 */
body[data-generating="true"] #chat .last_mes::before {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  background: var(--ui-bg-ai-solid) !important;
}
body[data-generating="true"] #chat .last_mes[is_user="true"]::before {
  background: var(--ui-bg-user-solid) !important;
}

/* 流式时关闭最后一条的角标（生成结束自动恢复） */
body[data-generating="true"] #chat .last_mes::after {
  display: none !important;
}

/* 流式时最后一条的文字阴影也关闭 */
body[data-generating="true"] #chat .last_mes .mes_text {
  text-shadow: none !important;
}

/* 不在视口的消息延迟渲染（配合 SillyTavern 的 .auto_hide） */
#chat .mes:not(.last_mes) {
  content-visibility: auto;
  contain-intrinsic-size: auto 120px;
}

/* ========== F) no-blur 兼容（纹理版） ========= */

/* 全局禁用模糊 - 基础重置 */
body.no-blur #top-settings-holder,
body.no-blur #left-nav-panel,
body.no-blur #right-nav-panel,
body.no-blur #top-settings-holder .drawer .drawer-content,
body.no-blur .popup:not(.transparent_dialogue_popup),
body.no-blur #send_form {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* AI 消息 - 纯实心色 */
body.no-blur .mes {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
body.no-blur .mes[is_user=false] {
  background: var(--ui-bg-ai-solid) !important;
}

/* 用户消息 - 纹理效果 */
body.no-blur .mes[is_user=true] {
  background:
    linear-gradient(135deg, rgba(22, 48, 82, 0.95) 0%, rgba(18, 40, 68, 0.9) 100%),
    var(--ui-noise-texture-strong) !important;
  background-blend-mode: overlay, normal !important;
}

/* 底边栏 - 纹理效果 */
body.no-blur #top-settings-holder {
  background:
    linear-gradient(180deg, rgba(8, 20, 35, 0.98) 0%, rgba(5, 16, 28, 0.95) 100%),
    var(--ui-noise-texture-soft) !important;
  background-blend-mode: overlay, normal !important;
}

/* Drawer 弹层 - 跟随底边栏纹理 */
body.no-blur #top-settings-holder .drawer .drawer-content {
  background:
    linear-gradient(180deg, rgba(8, 20, 35, 0.98) 0%, rgba(5, 16, 28, 0.95) 100%),
    var(--ui-noise-texture-soft) !important;
  background-blend-mode: overlay, normal !important;
}

/* 侧边栏 - 纯实心色 */
body.no-blur #left-nav-panel,
body.no-blur #right-nav-panel {
  background: var(--ui-bg-primary) !important;
}

/* 发送区域 - 深色实心 */
body.no-blur #send_form {
  background: rgba(5, 14, 26, 0.98) !important;
}

/* 弹窗 - 纯实心色 */
body.no-blur .popup:not(.transparent_dialogue_popup) {
  background: var(--ui-bg-primary) !important;
}
